begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(p_uid uuid, p_email text) returns void language plpgsql as $$
begin
  perform set_config('role','authenticated', true);
  perform set_config('request.jwt.claims', json_build_object('sub',p_uid,'email',p_email,'role','authenticated')::text, true);
end $$;
insert into auth.users (instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
values ('00000000-0000-0000-0000-000000000000','aa330000-0000-0000-0000-000000000033','authenticated','authenticated','schedule-a@t.co','{}','{}',now(),now(),'','','','');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
create temporary table ctx as select public.create_project('Schedules','UTC','GBP','2026-01-01',null,'team_project') project_id;
create temporary table cat as select id from public.project_areas where false;
insert into cat select id from public.project_areas where false;
set local role postgres;
insert into public.project_areas(project_id,title) select project_id,'Travel' from ctx;
insert into cat select id from public.project_areas where project_id=(select project_id from ctx);
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
create temporary table item as select (public.create_activity_in_category((select project_id from ctx),(select id from cat),' {"title":"Venue","kind":"other","activity_type":"task","estimated_cost_minor":4000}',null)).id;
select lives_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'Deposit',1000,'2026-10-01' from ctx,item$$,'Authorized schedule creation');
select lives_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'Balance',3000,'2026-11-01' from ctx,item$$,'Schedule can reconcile to Activity cost');
select is((select total_cost_minor from public.v_project_financials where project_id=(select project_id from ctx)),4000::bigint,'Schedule rows do not increase project cost');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,s.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'deposit','outgoing','paid',600,current_date from ctx,item,public.activity_payment_schedules s where s.commitment_id=item.id and s.title='Deposit'$$,'Partial scheduled payment');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,s.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'deposit','outgoing','paid',400,current_date from ctx,item,public.activity_payment_schedules s where s.commitment_id=item.id and s.title='Deposit'$$,'Second scheduled payment');
select is((select net_paid_minor from public.v_activity_payment_schedule_financials where title='Deposit'),1000::bigint,'Schedule paid total derives from payments');
select is((select outstanding_minor from public.v_activity_payment_schedule_financials where title='Deposit'),0::bigint,'Fully paid schedule has no outstanding amount');
select throws_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,s.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'balance','outgoing','paid',3001,current_date from ctx,item,public.activity_payment_schedules s where s.commitment_id=item.id and s.title='Balance'$$,'P0001',null,'Over-allocation is rejected');
select throws_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'Too much',1,'2026-12-01' from ctx,item$$,'P0001',null,'Schedule total above Activity cost is rejected');
select ok(not exists(select 1 from information_schema.tables where table_schema='public' and table_name='financial_obligations'),'Phase 6 does not add a financial obligations table');

-- Installed schema lifecycle and security; all identifiers stay inside this fixture.
create temp table deposit as select id from public.activity_payment_schedules where commitment_id=(select id from item) and title='Deposit';
create temp table balance as select id from public.activity_payment_schedules where commitment_id=(select id from item) and title='Balance';
select lives_ok($$update public.activity_payment_schedules set title='Venue deposit',due_on=current_date+2 where id=(select id from deposit)$$,'Label and date editable');
select throws_ok($$update public.activity_payment_schedules set amount_minor=999 where id=(select id from deposit)$$,'P0001',null,'Cannot reduce below net paid');
select throws_ok($$update public.commitments set estimated_cost_minor=3999 where id=(select id from item)$$,'P0001',null,'Cannot reduce Activity cost below schedule');
select throws_ok($$update public.activity_payment_schedules set deleted_at=now() where id=(select id from deposit)$$,'P0001',null,'Cannot remove paid history');
select throws_ok($$update public.payments set payment_schedule_id=null where payment_schedule_id=(select id from deposit)$$,'P0001',null,'Cannot clear paid allocation');
select throws_ok($$update public.payments set payment_schedule_id=(select id from balance) where payment_schedule_id=(select id from deposit)$$,'P0001',null,'Cannot move paid allocation');
select throws_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'Invalid',0,current_date from ctx,item$$,'23514',null,'Positive amount required');
select throws_ok($$update public.activity_payment_schedules set due_on=null where id=(select id from balance)$$,'23502',null,'Date required');
select lives_ok($$update public.activity_payment_schedules set amount_minor=2900 where id=(select id from balance)$$,'Unpaid amount editable');
select lives_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'Disposable',100,current_date+30 from ctx,item$$,'Create removable schedule');
select lives_ok($$select public.soft_delete_payment_schedule((select id from public.activity_payment_schedules where commitment_id=(select id from item) and title='Disposable'))$$,'Soft delete without history');
select is((select count(*)::int from public.activity_payment_schedules where commitment_id=(select id from item)),2,'Deleted schedule hidden');
select lives_ok($$update public.activity_payment_schedules set amount_minor=3000 where id=(select id from balance)$$,'Restore unpaid balance');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,deposit.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'refund','incoming','paid',200,current_date from ctx,item,deposit$$,'Allocated refund recorded');
select is((select outstanding_minor from public.v_activity_payment_schedule_financials where payment_schedule_id=(select id from deposit)),200::bigint,'Refund reopens outstanding');
select is((select refunded_minor from public.v_activity_payment_schedule_financials where payment_schedule_id=(select id from deposit)),200::bigint,'Refund displayed separately');
select throws_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,deposit.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'refund','incoming','paid',801,current_date from ctx,item,deposit$$,'P0001',null,'Cannot over-refund schedule');
select throws_ok($$update public.commitments set status='completed' where id=(select id from item)$$,'P0001',null,'Partial schedule cannot bypass completion gating');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,deposit.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'balance','outgoing','paid',200,current_date from ctx,item,deposit$$,'Repay refunded portion');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.project_id,item.id,balance.id,(select id from public.project_members where project_id=ctx.project_id and user_id=auth.uid()),'balance','outgoing','paid',3000,current_date from ctx,item,balance$$,'Finish balance');
select lives_ok($$update public.commitments set status='completed' where id=(select id from item)$$,'Fully paid scheduled Activity completes');
select is((select total_cost_minor from public.v_project_financials where project_id=(select project_id from ctx)),4000::bigint,'Cost still excludes schedule allocations');
select is((select net_actual_spend_minor from public.v_project_financials where project_id=(select project_id from ctx)),4000::bigint,'Spent follows actual net payments');
-- A separate future Activity tests derived state and the central emitter.
create temp table due_item as select (public.create_activity_in_category((select project_id from ctx),(select id from cat),'{"title":"Due Activity","kind":"other","activity_type":"task","estimated_cost_minor":1000}',null)).id;
create temp table due_schedule as with s as(insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.project_id,due_item.id,'Due balance',1000,current_date+2 from ctx,due_item returning id) select * from s;
select is((select count(*)::int from public.get_project_health((select project_id from ctx)) where subject_type='payment_schedule' and subject_id=(select id from due_schedule)),1,'One due-soon Health finding');
select is((select count(*)::int from public.get_project_timeline_events((select project_id from ctx),now()-interval '1 day',now()+interval '10 days') where event_type='payment_schedule_due' and subject_id=(select id from due_item) and all_day and status='due_soon'),1,'One date-only Timeline deadline');
select lives_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,type,status,amount_minor,due_on) select ctx.project_id,due_item.id,due_schedule.id,'balance','scheduled',1000,current_date+2 from ctx,due_item,due_schedule$$,'Legacy scheduled payment can reference allocation');
select is((select count(*)::int from public.get_project_timeline_events((select project_id from ctx),now()-interval '1 day',now()+interval '10 days') where event_type='payment_due'),0,'Linked ledger deadline not duplicated');
select is((select count(*)::int from public.get_project_health((select project_id from ctx)) where subject_type in ('payment_schedule','payment')),1,'Linked ledger Health finding not duplicated');
select throws_ok($$select app.evaluate_payment_schedule_deadlines()$$,'42501',null,'Authenticated cannot run scheduler');
select throws_ok($$select app.emit_domain_event('payment.due_soon',(select project_id from ctx),(select id from due_schedule),'{}','spoof')$$,'42501',null,'Client cannot spoof due event');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select app.evaluate_payment_schedule_deadlines()$$,'Trusted evaluator succeeds');
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule) and event_type='payment.due_soon'),1,'One due event');
select is((select count(*)::int from app.domain_event_processing ep join app.domain_events e on e.id=ep.event_id where e.resource_id=(select id from due_schedule)),1,'One processing receipt');
select is((select count(*)::int from app.automation_action_runs ar join app.domain_events e on e.id=ar.event_id where e.resource_id=(select id from due_schedule)),1,'One action receipt');
select is((select count(*)::int from public.notifications where payment_schedule_id=(select id from due_schedule)),1,'Unassigned falls back to one Organizer');
select ok((select actor_user_id is null and payload=jsonb_build_object('activity_id',(select id from due_item)) from app.domain_events where resource_id=(select id from due_schedule)),'System actor and minimal payload');
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from public.notifications where payment_schedule_id=(select id from due_schedule)),1,'Repeated scan does not resend');
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),1,'Repeated scan does not recreate fact');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
select is((select count(*)::int from public.v_my_payment_notifications where project_id=(select project_id from ctx)),1,'Recipient reads inbox');
select lives_ok($$update public.activity_payment_schedules set due_on=current_date+30 where id=(select id from due_schedule)$$,'Reschedule future');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),1,'Future date does not emit obsolete event');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
update public.activity_payment_schedules set due_on=current_date+3 where id=(select id from due_schedule);
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),2,'New qualifying date produces new fact');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
update public.payments set status='paid',paid_on=current_date where commitment_id=(select id from due_item);
select is((select count(*)::int from public.get_project_health((select project_id from ctx)) where subject_type='payment_schedule'),0,'Paid finding disappears');
update public.activity_payment_schedules set due_on=current_date+4 where id=(select id from due_schedule);
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),2,'Paid schedule never emits');
-- Roles and lifecycle isolation.
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('37000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','schedule-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,3) i;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.project_id,('37000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Schedule member',case when i=1 then 'member' else 'viewer' end::public.member_role,'active' from ctx,generate_series(1,2) i;
select pg_temp.login('37000000-0000-4000-8000-000000000001','schedule-test-1@example.test');
select lives_ok($$update public.activity_payment_schedules set title='Member edited' where id=(select id from balance)$$,'Member matches Activity financial management');
select pg_temp.login('37000000-0000-4000-8000-000000000002','schedule-test-2@example.test');
select is((select count(*)::int from public.activity_payment_schedules where id=(select id from balance)),1,'Viewer reads schedule');
select throws_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select project_id,id,'No',1,current_date from ctx,item$$,'42501',null,'Viewer cannot create');
update public.activity_payment_schedules set title='Viewer attack' where id=(select id from balance);
select is((select title from public.activity_payment_schedules where id=(select id from balance)),'Member edited','Viewer update affects zero rows');
select is((select count(*)::int from public.v_my_payment_notifications where project_id=(select project_id from ctx)),0,'Nonrecipient cannot read inbox');
select pg_temp.login('37000000-0000-4000-8000-000000000003','schedule-test-3@example.test');
select is((select count(*)::int from public.activity_payment_schedules where project_id=(select project_id from ctx)),0,'Nonmember sees no schedules');
select is((select count(*)::int from public.v_activity_payment_schedule_financials where project_id=(select project_id from ctx)),0,'Nonmember sees no schedule financials');
create temp table other as select public.create_project('Other schedules','UTC','GBP','2026-01-01') id;
select throws_ok($$insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select other.id,item.id,'Cross project',1,current_date from other,item$$,'42501',null,'Cross-project Activity binding denied');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');

create temp table responsible_item as select (public.create_activity_in_category((select project_id from ctx),(select id from cat),jsonb_build_object('title','Assigned reminder','kind','other','activity_type','task','estimated_cost_minor',1000,'owner_member_id',(select id from public.project_members where project_id=(select project_id from ctx) and user_id='37000000-0000-4000-8000-000000000001')),null)).id;
create temp table responsible_schedule as with s as(insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.project_id,responsible_item.id,'Assigned payment',1000,current_date+7 from ctx,responsible_item returning id) select * from s;
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select array_agg(recipient_user_id)::text from public.notifications where payment_schedule_id=(select id from responsible_schedule)),'{37000000-0000-4000-8000-000000000001}','Active assignee only, no Organizer or all-member fanout');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
update public.commitments set owner_member_id=null where id=(select id from responsible_item);
update public.activity_payment_schedules set due_on=current_date+6 where id=(select id from responsible_schedule);
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from public.notifications where payment_schedule_id=(select id from responsible_schedule) and recipient_user_id='aa330000-0000-0000-0000-000000000033'),1,'New date without assignee falls back to Organizer');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
update public.activity_payment_schedules set due_on=current_date-1 where id=(select id from responsible_schedule);
select is((select severity from public.get_project_health((select project_id from ctx)) where subject_id=(select id from responsible_schedule)),'blocker','Overdue is dynamically urgent');
select is((select status from public.get_project_timeline_events((select project_id from ctx),now()-interval '2 days',now()+interval '2 days') where event_type='payment_schedule_due' and subject_id=(select id from responsible_item)),'overdue','Timeline reflects overdue');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from responsible_schedule)),2,'No separate overdue or daily event');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
select throws_ok($$insert into public.payments(project_id,commitment_id,payment_schedule_id,type,status,amount_minor,paid_on) select ctx.project_id,item.id,responsible_schedule.id,'deposit','paid',1,current_date from ctx,item,responsible_schedule$$,'P0001',null,'Payment cannot allocate to another Activity');
update public.projects set timezone='Pacific/Kiritimati' where id=(select project_id from ctx);
update public.activity_payment_schedules set due_on=(now() at time zone 'Pacific/Kiritimati')::date where id=(select id from responsible_schedule);
select is((select status from public.get_project_timeline_events((select project_id from ctx),now()-interval '2 days',now()+interval '2 days') where event_type='payment_schedule_due' and subject_id=(select id from responsible_item)),'due_today','Due today uses project calendar');
select is((select occurs_at from public.get_project_timeline_events((select project_id from ctx),now()-interval '2 days',now()+interval '2 days') where event_type='payment_schedule_due' and subject_id=(select id from responsible_item)),((now() at time zone 'Pacific/Kiritimati')::date::timestamp at time zone 'Pacific/Kiritimati'),'All-day projection uses project timezone');
update public.activity_payment_schedules set due_on=(now() at time zone 'Pacific/Kiritimati')::date+5 where id=(select id from responsible_schedule);

update public.projects set status='archived' where id=(select project_id from ctx);
select throws_ok($$update public.activity_payment_schedules set title='Archived edit' where id=(select id from balance)$$,'P0001',null,'Archive denies schedule edit');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_payment_schedule_deadlines();
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),2,'Archive produces no reminder');
select is((select count(*)::int from app.domain_events where resource_id=(select id from responsible_schedule)),2,'Unpaid archived schedule does not emit');
select pg_temp.login('aa330000-0000-0000-0000-000000000033','schedule-a@t.co');
update public.projects set status='active' where id=(select project_id from ctx);
select lives_ok($$select public.soft_delete_project((select project_id from ctx))$$,'Normal project cleanup preserves financial history');
select is((select count(*)::int from public.activity_payment_schedules where project_id=(select project_id from ctx)),0,'Deleted project hides schedules');
select is((select count(*)::int from public.v_my_payment_notifications where project_id=(select project_id from ctx)),0,'Deleted project hides reminder inbox');
set local role postgres;
select is((select count(*)::int from app.domain_events where resource_id=(select id from due_schedule)),2,'Cleanup preserves facts');
select is((select count(*)::int from app.domain_event_processing ep join app.domain_events e on e.id=ep.event_id where e.resource_id=(select id from due_schedule)),2,'Cleanup preserves receipts');

select * from finish();
rollback;
